package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"math"
	"net/http"
	"os"
	"os/signal"
	"sync"
	"sync/atomic"
	"syscall"
	"time"
)

const (
	maxRequestBodyBytes = 1 << 20 // 1 MiB
	maxBatchSize        = 1024
	maxFeatures         = 4096
	maxCacheEntries     = 10000
)

type ModelWeights struct {
	Layers [][]float64
	Bias   []float64
}

type InferenceRequest struct {
	Features  []float64 `json:"features"`
	ModelID   string    `json:"model_id"`
	BatchSize int       `json:"batch_size"`
	Priority  int       `json:"priority"`
}

type InferenceResponse struct {
	Prediction float64 `json:"prediction"`
	LatencyMs  int64   `json:"latency_ms"`
	Cached     bool    `json:"cached"`
}

type ResourcePool struct {
	mu          sync.RWMutex
	allocated   int64
	capacity    int64
	borrowLog   map[string]int64
	repayWindow time.Duration
}

type InferenceServer struct {
	models       map[string]*ModelWeights
	pool         *ResourcePool
	shutdownFlag int32
	activeReqs   sync.WaitGroup
	cache        sync.Map
	cacheCount   int64
}

func NewResourcePool(capacity int64) *ResourcePool {
	return &ResourcePool{
		capacity:    capacity,
		borrowLog:   make(map[string]int64),
		repayWindow: 100 * time.Millisecond,
	}
}

func (rp *ResourcePool) Borrow(clientID string, amount int64) bool {
	rp.mu.Lock()
	defer rp.mu.Unlock()
	if rp.allocated+amount <= rp.capacity {
		rp.allocated += amount
		rp.borrowLog[clientID] += amount
		return true
	}
	return false
}

func (rp *ResourcePool) Repay(clientID string, amount int64) {
	rp.mu.Lock()
	defer rp.mu.Unlock()
	rp.allocated -= amount
	rp.borrowLog[clientID] -= amount
}

func (rp *ResourcePool) FlashBorrow(clientID string, amount int64, operation func() error) error {
	rp.mu.Lock()
	// Flash borrow: temporarily exceed capacity, must repay within same transaction
	originalAllocated := rp.allocated
	rp.allocated += amount
	rp.borrowLog[clientID] += amount
	// Hold lock for entire operation to prevent concurrent state manipulation
	err := operation()

	// Repay the flash loan
	rp.allocated -= amount
	rp.borrowLog[clientID] -= amount

	// Invariant check: pool should be back to original state
	if rp.allocated != originalAllocated {
		rp.mu.Unlock()
		return fmt.Errorf("flash borrow invariant violated")
	}
	rp.mu.Unlock()
	return err
}

func NewInferenceServer() *InferenceServer {
	server := &InferenceServer{
		models: make(map[string]*ModelWeights),
		pool:   NewResourcePool(1000),
	}
	server.models["default"] = &ModelWeights{
		Layers: [][]float64{{0.5, -0.3, 0.8}, {0.2, 0.7, -0.1}},
		Bias:   []float64{0.1, -0.05},
	}
	return server
}

func (s *InferenceServer) sigmoid(x float64) float64 {
	return 1.0 / (1.0 + math.Exp(-x))
}

func (s *InferenceServer) runInference(req *InferenceRequest) float64 {
	model, exists := s.models[req.ModelID]
	if !exists {
		model = s.models["default"]
	}
	result := 0.0
	for i, layer := range model.Layers {
		for j, weight := range layer {
			if j < len(req.Features) {
				result += weight * req.Features[j]
			}
		}
		if i < len(model.Bias) {
			result += model.Bias[i]
		}
	}
	return s.sigmoid(result)
}

func (s *InferenceServer) handleInference(w http.ResponseWriter, r *http.Request) {
	if atomic.LoadInt32(&s.shutdownFlag) == 1 {
		http.Error(w, "server shutting down", http.StatusServiceUnavailable)
		return
	}
	s.activeReqs.Add(1)
	defer s.activeReqs.Done()

	// Limit request body size to prevent memory-exhaustion DoS.
	r.Body = http.MaxBytesReader(w, r.Body, maxRequestBodyBytes)

	var req InferenceRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "invalid request", http.StatusBadRequest)
		return
	}

	// Validate input bounds to prevent integer overflow and abuse.
	if req.BatchSize < 0 || req.BatchSize > maxBatchSize {
		http.Error(w, "invalid batch size", http.StatusBadRequest)
		return
	}
	if len(req.Features) > maxFeatures {
		http.Error(w, "too many features", http.StatusBadRequest)
		return
	}

	start := time.Now()
	clientID := r.Header.Get("X-Client-ID")
	if clientID == "" {
		clientID = "anonymous"
	}

	// Compute resource requirement using int64 arithmetic to avoid overflow.
	resourceNeeded := int64(len(req.Features)) * int64(req.BatchSize)
	if resourceNeeded <= 0 {
		resourceNeeded = 1
	}

	var prediction float64
	var cached bool

	cacheKey := fmt.Sprintf("%s:%v", req.ModelID, req.Features)
	if val, ok := s.cache.Load(cacheKey); ok {
		prediction = val.(float64)
		cached = true
	} else {
		if req.Priority > 5 {
			// High priority: use flash borrow for burst capacity.
			// Guard against overflow when scaling the borrow amount.
			flashAmount := resourceNeeded
			if flashAmount > math.MaxInt64/10 {
				http.Error(w, "resource constraint", http.StatusTooManyRequests)
				return
			}
			flashAmount *= 10
			err := s.pool.FlashBorrow(clientID, flashAmount, func() error {
				prediction = s.runInference(&req)
				return nil
			})
			if err != nil {
				http.Error(w, "resource constraint", http.StatusTooManyRequests)
				return
			}
		} else {
			if !s.pool.Borrow(clientID, resourceNeeded) {
				http.Error(w, "resource exhausted", http.StatusTooManyRequests)
				return
			}
			prediction = s.runInference(&req)
			s.pool.Repay(clientID, resourceNeeded)
		}
		// Cap cache size to prevent unbounded memory growth.
		if atomic.LoadInt64(&s.cacheCount) < maxCacheEntries {
			if _, loaded := s.cache.LoadOrStore(cacheKey, prediction); !loaded {
				atomic.AddInt64(&s.cacheCount, 1)
			}
		}
	}

	resp := InferenceResponse{
		Prediction: prediction,
		LatencyMs:  time.Since(start).Milliseconds(),
		Cached:     cached,
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(resp)
}

func (s *InferenceServer) handleHealth(w http.ResponseWriter, r *http.Request) {
	s.pool.mu.RLock()
	defer s.pool.mu.RUnlock()
	status := map[string]interface{}{
		"status":    "healthy",
		"allocated": s.pool.allocated,
		"capacity":  s.pool.capacity,
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(status)
}

func main() {
	server := NewInferenceServer()

	mux := http.NewServeMux()
	mux.HandleFunc("/inference", server.handleInference)
	mux.HandleFunc("/health", server.handleHealth)

	httpServer := &http.Server{
		Addr:         ":8080",
		Handler:      mux,
		ReadTimeout:  10 * time.Second,
		WriteTimeout: 10 * time.Second,
	}

	go func() {
		log.Printf("Starting inference server on :8080")
		if err := httpServer.ListenAndServe(); err != http.ErrServerClosed {
			log.Fatalf("Server error: %v", err)
		}
	}()

	quit := make(chan os.Signal, 1)
	signal.Notify(quit, syscall.SIGINT, syscall.SIGTERM)
	<-quit

	log.Println("Initiating graceful shutdown...")
	atomic.StoreInt32(&server.shutdownFlag, 1)

	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()

	server.activeReqs.Wait()
	if err := httpServer.Shutdown(ctx); err != nil {
		log.Fatalf("Shutdown error: %v", err)
	}
	log.Println("Server stopped")
}
